    "css": "/* 全局属性 */\n\n#nice {\n  font-family: \"PingFang SC\", \"Microsoft YaHei\", sans-serif;\n  word-break: break-all;\n}\n\n/* 标题 */\n#nice h1 {\n  font-size: 1.7em;\n  font-weight: normal;\n  border-bottom: 2px solid hsl(216, 100%, 68%);\n}\n\n#nice h1 .content {\n  background: hsl(216, 100%, 68%);\n  color: white;\n  padding: 3px 10px;\n  border-top-right-radius: 3px;\n  border-top-left-radius: 3px;\n  margin-right: 3px;\n}\n\n#nice h2 {\n  font-weight: normal;\n  color: #333;\n  font-size: 1.4em;\n  border-bottom: 1px solid hsl(216, 100%, 68%);\n}\n\n#nice h2 .content {\n  border-bottom: 1px solid hsl(216, 100%, 68%);\n}\n\n#nice h3 {\n  font-weight: normal;\n  color: #333;\n  font-size: 1.2em;\n}\n\n/* 特殊规定：\n * h4 → 摘要\n * h5 → 强调\n * h6 → 序号\n * em → 高亮\n */\n\n#nice h4 {\n  font-weight: normal;\n  font-size: 1em;\n  width: 80%;\n  border: 1px solid hsl(216, 100%, 68%);\n  border-top: 4px solid hsl(216, 100%, 68%);\n  padding: 10px;\n  margin: 30px auto;\n  color: #333;\n}\n\n#nice h5 {\n  font-weight: normal;\n  font-size: 1.3em;\n  text-align: center;\n  background: hsl(216, 100%, 68%);\n  border: 3px double #fff;\n  width: 80%;\n  padding: 10px;\n  margin: 30px auto;\n  color: #fff;\n}\n\n#nice h6 {\n  font-size: 1.5em;\n  font-weight: normal;\n  color: hsl(216, 100%, 68%);\n  border-bottom: 1px solid hsl(216, 100%, 68%);\n}\n\n#nice em {\n  font-style: normal;\n  font-weight: normal;\n  color: white;\n  background: hsl(244, 100%, 75%);\n  padding: 2px 4px;\n\tmargin: 0px 2px;\n}\n\n/* 其他块元素 */\n\n#nice ol,\n#nice ul {\n  padding-left: 2em;\n}\n\n#nice hr {\n  width: 90%;\n  margin: 1.5em auto;\n  border-top: 2px dashed hsl(216, 100%, 68%);\n}\n\n#nice table {\n  margin: 1.5em auto;\n  width: auto;\n}\n\n#nice img {\n  width: 90%;\n  margin: 0 auto;\n  box-shadow: #CCC 0 10px 15px;\n}\n\n#nice blockquote {\n  background: #f9f9f9;\n  border-left-color: hsl(216, 100%, 68%);\n}\n\n#nice blockquote p {\n  color: #999;\n  padding: 3px 0;\n}\n\n#nice a span {\n  color: hsl(187, 100%, 45%);\n  font-weight: normal;\n  border-bottom-color: hsl(187, 100%, 45%);\n}\n\n#nice strong {\n  color: hsl(216, 80%, 44%);\n}\n\n#nice s,\n#nice del {\n  color: #999;\n}\n\n#nice p,\n#nice li,\n#nice li span,\n#nice h4,\n#nice table tr td {\n  color: #666;\n}\n\n#nice table tr th {\n  color: #333;\n  font-weight: normal;\n}\n\n#nice p code,\n#nice li code {\n  color: hsl(216, 100%, 68%);\n}\n\n#nice sup {\n  line-height: 1;\n}\n\n#nice .footnote-word,\n.footnote-ref {\n  font-weight: normal;\n  color: hsl(187, 100%, 45%);\n}\n\n#nice .footnotes-sep {\n  font-family: inherit;\n}\n\n#nice .footnote-num {\n  font-family: inherit;\n}\n\n#nice .footnote-item p {\n  color: #666;\n}\n\n#nice .footnote-item p em {\n  color: #999;\n  background: transparent;\n}\n\n/* 行间公式\n * 最大宽度 max-width: 300% !important;\n */\n#nice .block-equation svg {\n}\n\n/* 行内公式\n */\n#nice .inline-equation svg {  \n}\n\n/* 滑动图片\n */\n#nice .imageflow-img {\n  display: inline-block;\n  width:100%;\n  margin-bottom: 0;\n}"
